import test from 'node:test';import assert from 'node:assert/strict';
import {newGame,newReturningGame,restore,save} from './simulation.js';
import {registrationCourses,registrationCatalog,generalCourseOptions,registeredCourseIds,confirmRegistration,timetable} from './timetable.js';
import {attendLesson} from './classes.js';
test('returning student already has required courses and no chosen generals',()=>{const s=newReturningGame();assert.equal(s.academics.registrationPending,true);const chosen=registrationCatalog(s).filter(c=>registeredCourseIds(s).includes(c.registrationId));assert.ok(chosen.length>=7);assert.ok(chosen.every(c=>c.required));assert.equal(timetable(newGame()).length,2);});
test('general is added without replacing a required class and governs actual attendance after save',()=>{let s=newReturningGame();s=confirmRegistration(s,[...registeredCourseIds(s),'1:coding']);s=restore(save(s));assert.ok(timetable(s).some(x=>x.id==='theory'));const c=timetable(s).find(x=>x.id==='coding');assert.equal(c.start,810);s.clock.minute=c.start;s.location=c.location;s.buildingArea={place:c.location,id:c.area};s=attendLesson(s,c.key,c.choices[0].id).state;assert.equal(s.academics.records[c.key].status,'present');});
test('only non-overlapping and affordable-credit generals are offered',()=>{const s=newReturningGame(),ids=registeredCourseIds(s);assert.ok(generalCourseOptions(s,ids).some(c=>c.id==='coding'));const selected=[...ids,'1:coding'];assert.ok(!generalCourseOptions(s,selected).some(c=>c.id==='media'));assert.throws(()=>confirmRegistration(s,[...selected,'1:media']));assert.throws(()=>confirmRegistration(s,ids.filter(x=>x!=='1:theory')));assert.throws(()=>confirmRegistration(s,[...ids,'invalid']));const full=[...selected,'2:film'];assert.equal(generalCourseOptions(s,full).length,0);});
test('future general can change but elapsed courses and NPC timetables stay untouched',()=>{let s=newReturningGame();s=confirmRegistration(s,[...registeredCourseIds(s),'1:coding']);s.clock.minute=920;assert.throws(()=>confirmRegistration(s,registeredCourseIds(s).filter(x=>x!=='1:coding')));const next=confirmRegistration(s,[...registeredCourseIds(s),'2:film']);assert.ok(timetable(next,'taei',2).some(c=>c.id==='film'));assert.equal(next.clock.minute,920);assert.deepEqual(timetable(next,'seoyeon',2),timetable(s,'seoyeon',2));});
test('older customized timetable retains its original course times across load',()=>{const s=newGame();s.academics.courseIds=['1:ensemble','1:coding','2:expression','2:vocal','3:chapel','3:stage'];const loaded=restore(save(s));assert.equal(timetable(loaded).find(c=>c.id==='coding').start,690);assert.equal(registrationCatalog(loaded).find(c=>c.id==='coding').start,690);});
